const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const query = String(body.knowledge_query || body.query || body.message || 'que sabemos del estado actual del proyecto?');
const scope = String(body.scope || 'project');
const includeSources = body.include_sources !== false;
const dryRun = body.dry_run !== false;

const prompt = [
  'Responde como Knowledge Agent del proyecto Invernadero Central.',
  `Consulta: ${query}.`,
  `Alcance solicitado: ${scope}.`,
  `Incluir fuentes: ${includeSources}.`,
  'Usa solo contexto versionado del repo central y referencias declaradas de sensores/web cuando sean relevantes.',
  'Prioriza: baseline actual, backlog, Kanban, roadmap, decisiones, V&V, roles, agentes, drafts y contexto conversacional versionado.',
  'Devuelve respuesta breve pero trazable: answer, source_refs, contradictions, missing_context y recommended_next_agent si aplica.',
  'Si hay contradicciones entre documentos, reportalas sin corregirlas.',
  'No muevas estados Kanban, no marques DONE, no edites HU congeladas, no inventes evidencia ni decisiones.',
  'Haz una sola pregunta si falta informacion critica.'
].join(' ');

return [{
  json: {
    agent: 'project-knowledge',
    workspace: 'central',
    prompt,
    mode: 'knowledge-query',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'WF-KNOWLEDGE-QUERY-001',
      agent_id: 'AGENT-KNOW-001',
      query,
      scope,
      include_sources: includeSources,
      requested_by: body.requested_by || 'chat-gateway'
    }
  }
}];
